head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > getPopupParam]<br/>팝업이 생성될때 전달된 데이터(Parameter)를 팝업 내부에서 조회하여 반환합니다.",
    "validation" : [
        "팝업에 전달된 데이터 문자열을 반환해야 합니다.",
        "XML 데이터인 경우 직렬화(serialize) 된 문자열을 반환해야 합니다.",
        "XML 이 아닌 경우 JSON.stringify 로 변환된 문자열을 반환해야 합니다.",
        "전달된 데이터가 없으면 null 을 반환해야 합니다.",
        "팝업 내부에서만 호출하여야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_openPopup_onclick = function () {
    var dataType = par_dataType.getValue();
    var dataObject;

    if (dataType === "xml") {
        dataObject = {type: "xml", name: "tmpData", data: "<data><name>테스트</name><value>100</value></data>"};
    } else if (dataType === "json") {
        dataObject = {type: "json", name: "tmpData", data: {name: "테스트", value: 100}};
    } else if (dataType === "string") {
        dataObject = {type: "string", name: "tmpData", data: "문자열 파라미터"};
    }

    var options = {
        id: "getPopupParam_1",
        type: "wframePopup",
        width: "600px",
        height: "350px",
        top: "100px",
        left: "100px",
        popupName: "테스트 팝업",
        modal: false
    };

    if (dataObject) {
        options.dataObject = dataObject;
    }

    $p.openPopup("/sample/common_link/p_getPopupParam_1.xml", options);

    wf_body_bottom.getObj("scwin").setReturnValue("openPopup 실행 (dataType: " + dataType + ")");
    wf_body_bottom.getObj("scwin").setReturnValue("팝업 내부에서 getPopupParam 결과를 확인하세요.");
}
